/* V28 pricing screens. The earlier free calculator remains available as a tab. */
'use strict';
const price28LegacyPage = pricingPage;
const price28Tabs = [['calculadora','Cotizador libre'],['recomendador','Precios del inventario'],['comparar','Comparar marketplaces']];
let price28Tab = 'calculadora';
let price28ComparisonOrigin='inventory';
let price28PickerQuery='';
const price28Targets=['Sears','Sanborns','Coppel','Mercado Libre','Liverpool','Tienda Nube','Elektra'];
function price28Channel(target){return ['Sears','Sanborns'].includes(target)?'T1 Comercios':target;}
function price28IsProduct(){return price28Tab==='recomendador'||price28Tab==='comparar'&&price28ComparisonOrigin==='inventory';}
function price28Logo(target){return window.MarketUI?.logo(target,'lg')||icon('layers');}
function price28Target(f){return f.targetMarket||(f.channel==='T1 Comercios'?'Sears':f.channel);}
function price28ApplyProposal(f){if(price28IsProduct()||price28Tab==='comparar')return;const accepted=f.categoryByChannel?.[f.channel],suggestion=f.name?price28Engine().suggestCategory?.(price28Config(),f.name,f.channel,price28Products()):'';if(accepted)f.category=accepted;else if(suggestion)f.category=suggestion;const select=document.getElementById('price28-category');if(select)select.value=f.category;}
function price28CompareCTA(r){return `<div class="price28-compare-cta">${price28Btn(`${icon('layers')} Comparar marketplaces ${icon('arrow')}`,'compare-start',`${!r.discount?'disabled':''}`,true)}<small>Conserva este escenario y compara los siete marketplaces.</small></div>`;}
function price28MarketButtons(f){return `<fieldset class="price28-market-field wide"><legend>¿En qué marketplace vas a cotizar?</legend><div class="price28-market-buttons" role="group" aria-label="Marketplace de la cotización">${price28Targets.map(target=>`<button type="button" data-price28-market="${esc(target)}" aria-pressed="${price28Target(f)===target}" class="${price28Target(f)===target?'active':''}">${price28Logo(target)}<span>${esc(target)}</span></button>`).join('')}</div></fieldset>`;}
function price28StartComparison(){const source=price28Forms[price28Tab];price28ComparisonOrigin=price28IsProduct()?'inventory':'free';price28Forms.comparar=structuredClone(source);price28Forms.comparar.categoryByChannel={...(source.categoryByChannel||{})};price28Tab='comparar';render();}

let price28PriceSelection={fingerprint:'',overrides:{}};
function price28TrafficRows(rows){return window.ERP?.engines?.pricingSignals?.classifyPricing(rows,price28Config())||rows.map(()=>({color:'red',title:'Cargando evaluación',reason:'Espera a que termine de cargar el motor de precios.',savable:false}));}
function price28Selection(rows){const signals=price28TrafficRows(rows),f=price28Forms.comparar,fingerprint=JSON.stringify([f.productKey,f.name,price28Config().pricingSignals,rows.map((r,i)=>[r.targetMarket,r.category,r.commissionRate,r.discount,r.regular,signals[i].color])]);if(fingerprint!==price28PriceSelection.fingerprint)price28PriceSelection={fingerprint,overrides:{}};return rows.map((r,i)=>({result:r,signal:signals[i],selected:signals[i].savable&&(Object.hasOwn(price28PriceSelection.overrides,r.targetMarket)?price28PriceSelection.overrides[r.targetMarket]:signals[i].color==='green'),manual:Object.hasOwn(price28PriceSelection.overrides,r.targetMarket)}));}
function price28TrafficVector(signal){return `<div class="price28-traffic-corner" title="${esc(signal.reason)}"><svg class="price28-traffic-vector" viewBox="0 0 34 78" role="img" aria-label="Semáforo ${signal.color==='green'?'verde':signal.color==='yellow'?'amarillo':'rojo'}: ${esc(signal.title)}"><rect x="1" y="1" width="32" height="76" rx="11" fill="#25364d"/>${[['red','#ef4444',16],['yellow','#fbbf24',39],['green','#20c997',62]].map(([color,fill,y])=>`<circle cx="17" cy="${y}" r="8" fill="${fill}" opacity="${signal.color===color?'1':'.23'}" ${signal.color===color?'stroke="white" stroke-width="1.5"':''}/>`).join('')}</svg></div>`;}
function price28Decision(r,signal){return `<div class="price28-decision price28-decision-${signal.color}" role="status"><strong>${esc(signal.title)}</strong><span>${esc(signal.reason)}</span><small>Referencia del cálculo: ${esc(r.valid?r.status:(r.errors||[]).map(e=>e.message).join(' '))}</small></div>`;}
function price28SelectionTools(rows){if(!price28IsProduct())return `<div class="price28-selection-tools"><p>Producto sin registrar: compara y exporta la cotización. Selecciona un producto del inventario para guardar precios por marketplace.</p><div>${price28Btn('Criterios del semáforo','signal-policy')}${price28Btn(`${icon('download')} Exportar`,'export')}</div></div>`;const selection=price28Selection(rows),count=selection.filter(r=>r.selected).length,red=selection.filter(r=>r.selected&&r.signal.color==='red').length,yellow=selection.filter(r=>r.selected&&r.signal.color==='yellow').length;return `<div class="price28-selection-tools">${price28IsProduct()?price28Btn(`${icon('check')} Guardar precios seleccionados (${count})`,'prepare',`${!count?'disabled':''}`,true):'<span>Producto sin registrar: puedes comparar y exportar su cotización.</span>'}<div>${price28Btn('Seleccionar verdes','select-green')}${price28Btn('Quitar selección','select-none')}${price28Btn('Criterios del semáforo','signal-policy')}${price28Btn(`${icon('download')} Exportar`,'export')}</div><p>${count} seleccionados${yellow?` · ${yellow} amarillos`:''}${red?` · ${red} rojos: se guardarán para revisión, fuera de la cola de envío`:''}. Puedes cambiar cada casilla. Al cambiar el cálculo se restablece la selección automática de verdes.</p></div>`;}
function price28RefreshSelection(){const el=document.getElementById('price28-selection-tools');if(el){const rows=price28Calculate();if(Array.isArray(rows))el.innerHTML=price28SelectionTools(rows);}}

