function price28ModalError(errors){const e=document.getElementById('price28-modal-error');if(e)e.innerHTML=`<div class="price28-error price28-card-gap">${errors.map(x=>esc(x.message||x)).join('<br>')}</div>`;}
async function price28Command(type,payload){
  if(price28Busy){toast('Espera a que termine de guardarse la propuesta actual.',true);return false;} price28Busy=true;
  try{const r=await ERP.command(type,payload);if(r?.ok===false){toast(r.error?.message||r.error||'No se pudo guardar.',true);return false;}return true;}
  catch(e){toast(e.message||'No se pudo guardar.',true);return false;}finally{price28Busy=false;}
}
function price28ExportCSV(filename,rows){
  const cell=v=>{let s=String(v??'');if(/^[=+@]/.test(s))s="'"+s;return `"${s.replace(/"/g,'""')}"`;};
  const blob=new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function price28Export(){
  const r=price28Calculate();
  if(Array.isArray(r)){price28ExportCSV('AIMERKA_comparativo_V28.csv',[['Canal','Categoría','Comisión','Precio descuento','Precio regular','Disponible de caja','Disponible tras envío','Tratamiento retenciones','Decisión'],...r.map(v=>[v.targetMarket||v.channel,v.category,v.commissionRate,v.discount?.price,v.regular?.price,v.discount?.profit,v.discount?.netPayout,v.retentionTreatment,v.status])]);return;}
  if(!r?.valid||!r.discount)return;
  const fields=[['Precio','price'],['Costo','cost'],['Envío','shipping'],['Comisión','commission'],['Retención IVA','vat'],['Retención ISR','isr'],['Pago neto','netPayout'],['Disponible de caja','profit'],['Margen comercial antes de retenciones','commercialProfit'],['Resultado objetivo','objectiveProfit'],['Depósito del market antes de envío','marketplacePayout'],['Retenciones estimadas','withholdingTotal'],['Margen','margin'],['Utilidad objetivo','targetProfit'],['Diferencia sobre venta','targetDifference']];
  price28ExportCSV('AIMERKA_precio_V28.csv',[['Contexto',r.context],['Canal',r.channel],['Categoría',r.category],['Tratamiento de retenciones',r.retentionTreatment==='no_pass_through'?'No trasladar retenciones':'Trasladar retenciones al precio'],['Concepto','Con descuento','Regular'],...fields.map(([label,key])=>[label,r.discount[key],r.regular?.[key]]),['Decisión',r.status]]);
}
function price28Clear(){
  const f=price28Forms[price28Tab];f.name='';f.manualDiscount='';f.manualRegular='';f.manualShipping='';f.alternateMarketPrice='';
  f.productKey='';f.lastPurchaseCost='';f.cost='';f.marketPrice='';f.msiComparisonPrice='';delete f.competitorReference;f.categoryByChannel={};f.categoryAcceptedTitle='';
  // Keep the user's channel, calculation mode and T1 choices when clearing a product.
  render();
}

document.addEventListener('input',event=>{
  if(event.target.id==='price28-picker-search'){price28PickerQuery=event.target.value;document.getElementById('price28-picker-results').innerHTML=price28ProductMatches(price28PickerQuery,Infinity,true);return;}
  const field=event.target.dataset.price28Field;
  if(field&&price28Forms[price28Tab]){const f=price28Forms[price28Tab];if(field==='productKey'&&f.productKey!==event.target.value){f.lastPurchaseCost='';const costField=document.getElementById('price28-lastPurchaseCost');if(costField)costField.value='';f.alternateMarketPrice='';f.msiComparisonPrice='';delete f.competitorReference;const marketField=document.getElementById('price28-alternateMarketPrice');if(marketField)marketField.value='';}if(field==='name'&&f.name!==event.target.value&&f.competitorReference){f.marketPrice='';delete f.competitorReference;const marketField=document.getElementById('price28-marketPrice');if(marketField)marketField.value='';}f[field]=event.target.value;if(['alternateMarketPrice','marketPrice'].includes(field))delete f.competitorReference;if(field==='category'){(f.categoryByChannel??={})[f.channel]=f.category;f.categoryAcceptedTitle=f.name;}price28RefreshResult();return;}
  if(event.target.dataset.price28Config){
    const t=event.target,s=t.dataset.price28Config,d=price28Draft(s),row=t.dataset.price28Row,field=t.dataset.price28Key;
    let value=t.type==='number'?(t.value===''?null:Number(t.value)):t.value;if(t.dataset.price28Percent==='1'&&value!==null)value/=100;
    if(row==='')d[field]=value;else if(d[Number(row)])d[Number(row)][field]=value;
  }
  if(event.target.dataset.price28SettlementChannel)price28Draft('settlement').shippingTreatment[event.target.dataset.price28SettlementChannel]=event.target.value;
  if(event.target.dataset.price28LiverpoolMsi!==undefined)price28Draft('settlement').liverpoolMsi[Number(event.target.dataset.price28LiverpoolMsi)].rate=event.target.value===''?null:Number(event.target.value)/100;
  if(event.target.id==='price28-config-query'){price28ConfigQuery=event.target.value;const cursor=event.target.selectionStart;render();const i=document.getElementById('price28-config-query');i?.focus();i?.setSelectionRange(cursor,cursor);}
});
document.addEventListener('change',event=>{
  if(event.target.dataset.price28SelectMarket){price28PriceSelection.overrides[event.target.dataset.price28SelectMarket]=event.target.checked;const note=event.target.closest?.('label')?.querySelector('small');if(note)note.textContent='Selección manual';price28RefreshSelection();return;}
  if(event.target.dataset.price28CompareCategory){const f=price28Forms.comparar;(f.categoryByChannel??={})[event.target.dataset.price28CompareCategory]=event.target.value;price28RefreshResult();return;}
  if(event.target.id==='price28-commission-channel'){price28CommissionChannel=event.target.value;price28ConfigQuery='';render();return;}
  const field=event.target.dataset.price28Field;
  if(field&&price28Forms[price28Tab]){
    price28Forms[price28Tab][field]=event.target.value;
    if(field==='category'){const f=price28Forms[price28Tab];(f.categoryByChannel??={})[f.channel]=f.category;f.categoryAcceptedTitle=f.name;}
    if(['channel','mode','productKey','name'].includes(field))price28RefreshForm(event.target);else price28RefreshResult();
  }
});
document.addEventListener('click',async event=>{
  const target=event.target.closest('[data-price28-market]');if(target){const f=price28Forms[price28Tab];f.targetMarket=target.dataset.price28Market;f.channel=price28Channel(f.targetMarket);f.category=f.categoryByChannel?.[f.channel]||price28Engine().listCategories(price28Config(),f.channel)[0];price28RefreshForm(target);return;}
  const pick=event.target.closest('[data-price28-pick]');if(pick){const f=price28Forms[price28Tab];if(f.productKey!==pick.dataset.price28Pick){f.lastPurchaseCost='';f.alternateMarketPrice='';f.msiComparisonPrice='';delete f.competitorReference;}f.productKey=pick.dataset.price28Pick;document.getElementById('modal')?.close();render();return;}
  const tab=event.target.closest('[data-price28-tab]');if(tab){price28Tab=tab.dataset.price28Tab;render();return;}
  const setting=event.target.closest('[data-price28-settings-tab]');if(setting){price28SettingsTab=setting.dataset.price28SettingsTab;price28ConfigQuery='';render();return;}
  const transferToggle=event.target.closest('[data-price28-transfer-toggle]');if(transferToggle){const f=price28Forms[price28Tab];f.transferEnabled=!f.transferEnabled;price28RefreshForm(transferToggle);return;}
  const retention=event.target.closest('[data-price28-retention]');if(retention){price28Forms[price28Tab].retentionTreatment=retention.dataset.price28Retention;price28RefreshOptions('retention',retention);return;}
  const mode=event.target.closest('[data-price28-mode]');if(mode){price28Forms[price28Tab].mode=mode.dataset.price28Mode;price28RefreshForm(mode);return;}
  const displayDiscount=event.target.closest('[data-price28-discount-mode]');if(displayDiscount){price28Forms[price28Tab].displayDiscountMode=displayDiscount.dataset.price28DiscountMode;price28RefreshOptions('discount',displayDiscount);return;}
  const rate=event.target.closest('[data-price28-rate]');if(rate){const f=price28Forms[price28Tab],value=rate.dataset.price28Value;f[rate.dataset.price28Rate]=value;if(rate.dataset.price28Rate==='margin'){f.zeroMarginInflation='0';f.mode=['recomendador','comparar'].includes(price28Tab)?'automatico':'tasas';}if(rate.dataset.price28Rate==='inflation'&&['precios','manual_precios'].includes(f.mode)&&Number(f.manualDiscount)>0)f.manualRegular=String(price28Engine().roundRegular99(Number(f.manualDiscount),Number(value)/100,price28Engine().pricePolicy(price28Config())));price28RefreshRates();return;}
  const b=event.target.closest('[data-price28-action]');if(!b)return;const action=b.dataset.price28Action;
  if(action==='competition'){const f=price28Forms[price28Tab],p=price28IsProduct()?price28FindProduct(f.productKey):null;if(price28IsProduct()&&!p){toast('Selecciona primero un producto.',true);return;}if(!window.CompetitionPricing){toast('La herramienta de competencia está cargando. Recarga AIMERKA.',true);return;}const originTab=price28Tab,originalKey=f.productKey;window.CompetitionPricing.open({name:p?.name||f.name,upc:/^\d{8,14}$/.test(String(p?.upc||''))?String(p.upc):'',onApply(price,reference){if(price28Tab!==originTab||price28Forms[originTab]!==f||f.productKey!==originalKey){toast('El producto o el escenario cambió. Vuelve a abrir el análisis.',true);return;}f[price28IsProduct()?'alternateMarketPrice':'marketPrice']=String(price);f.competitorReference=reference;f.mode='competitivo';render();toast('Referencia aplicada. El modo competitivo muestra la caja disponible a ese precio.');}});return;}
  if(action==='compare-start'){price28StartComparison();return;}
  if(action==='picker'){price28PickerQuery='';showModal(`<div class="price28-picker"><h2>${icon('box')} Elegir producto del inventario</h2><p>Catálogo completo, incluidos productos sin existencias e inactivos. Busca por nombre, UPC o SKU. Seleccionar no modifica el producto.</p><label for="price28-picker-search">Buscar en el catálogo</label><input type="search" id="price28-picker-search" placeholder="Ej. Dyson, Apple, un UPC o SKU"><div id="price28-picker-results" class="price28-picker-results">${price28ProductMatches('',Infinity,true)}</div><div class="modal-actions">${price28Btn('Cerrar','modal-close')}</div></div>`);document.getElementById('price28-picker-search')?.focus();return;}
  if(action==='compare-category'){(price28Forms.comparar.categoryByChannel??={})[b.dataset.price28Channel]=b.dataset.price28Category;price28RefreshResult();return;}
  if(action==='calculate'){price28RefreshResult();return;}
  if(action==='clear'){price28Clear();return;}
  if(action==='configuration'){navigate('configuration');return;}
  if(action==='back-pricing'){navigate('pricing');return;}
  if(action==='modal-close'){document.getElementById('modal').close();return;}
  if(action==='suggestion'){const f=price28Forms[price28Tab];f.category=b.dataset.price28Category;f.categoryAcceptedTitle=f.name;(f.categoryByChannel??={})[f.channel]=f.category;render();return;}
  if(action==='export'){price28Export();return;}
  if(action==='export-queue'){ERP.downloadCSV('AIMERKA-precios-preparados',(state.pricePublicationQueue||[]).filter(r=>r.status==='awaiting_connection'&&!state.products.find(p=>p.sku===r.sku)?.lifecycle?.hidden).map(r=>({sku:r.sku,upc:r.upc,marketplace:r.targetMarket||r.channel,precio_descuento_mxn:r.discountCents/100,precio_regular_mxn:r.regularCents/100,moneda:r.currency,estado:'Pendiente de conexión',fecha:r.createdAt})));return;}
  if(action==='select-green'||action==='select-none'){const rows=price28Calculate();if(Array.isArray(rows)){price28Selection(rows);price28PriceSelection.overrides=action==='select-green'?{}:Object.fromEntries(rows.map(r=>[r.targetMarket,false]));price28RefreshResult();}return;}
  if(action==='signal-policy'){const policy=window.ERP.engines.pricingSignals.signalPolicy(price28Config());showModal(`<h2 id="modal-title">Criterios del semáforo</h2><p>Rojo si no hay utilidad comercial o caja positiva. El amarillo señala margen de caja bajo; estos límites no cambian los precios ni las retenciones.</p><form id="price28-signal-policy"><label>Mínimo de margen de caja sobre venta (%)<input name="minCashMargin" type="number" min="0" max="100" step="0.1" value="${policy.minCashMargin*100}" required></label><label>Mínimo frente a la mediana de otros canales (%)<input name="peerCashRatio" type="number" min="0" max="100" step="1" value="${policy.peerCashRatio*100}" required></label><small>Ejemplo: 50% significa que se marca amarillo cuando el margen de caja es menor a la mitad de la mediana positiva de los demás canales.</small><div class="modal-actions">${price28Btn('Cerrar','modal-close')}<button class="btn primary" type="submit">Guardar criterios</button></div></form>`);return;}
  if(action==='prepare'){const f=price28Forms[price28Tab],p=price28FindProduct(f.productKey);if(!p){toast('Selecciona un producto por SKU o UPC.',true);return;}const results=price28Calculate(),rows=Array.isArray(results)?results:[{...results,targetMarket:price28Target(f)}],selection=Array.isArray(results)?price28Selection(rows):rows.map((r,i)=>({result:r,signal:price28TrafficRows(rows)[i],selected:true})),chosen=b.dataset.price28Target?selection.filter(r=>r.result.targetMarket===b.dataset.price28Target):Array.isArray(results)?selection.filter(r=>r.selected):selection;if(!chosen.length){toast('Selecciona al menos un marketplace para guardar.',true);return;}const risk=chosen.filter(r=>r.signal.color==='red').map(r=>r.result.targetMarket);await price28Command('pricing.publication.prepare',{productSku:p.sku,targets:chosen.map(r=>r.result.targetMarket),riskAcknowledgedTargets:risk,input:price28Input()});return;}


  if(action==='save'){
    const r=price28Calculate();if(!r?.valid||!r.discount)return;
    if(!price28IsProduct()&&price28Forms[price28Tab].name&&!price28Forms[price28Tab].categoryByChannel?.[r.channel]){toast('Confirma la categoría sugerida o selecciona una categoría antes de guardar.',true);return;}
    const f=price28Forms[price28Tab],p=price28FindProduct(f.productKey),name=f.name||`${price28Tab==='recomendador'?(p?.name||'Producto'):'Escenario'} · ${r.channel}`;
    if(await price28Command('pricing.scenario.save',{name,context:r.context,input:price28Input(),productSku:price28Tab==='recomendador'?p?.sku:null})){toast('Escenario V28 guardado.');render();}return;
  }
  if(action==='scenario'){
    const s=state.pricingScenarios?.[Number(b.dataset.price28Index)];if(!s)return;
    showModal(`<div class="price28-modal"><h2>${esc(s.name||'Escenario guardado')}</h2><p class="modal-subtitle">Resultado conservado al guardar. No recalcula con cambios posteriores.</p>${s.result?`<p class="info-box">Criterio guardado: ${s.result.retentionTreatment==='no_pass_through'?'no sumar retenciones al objetivo de precio':'cubrir retenciones en el objetivo de precio'}. La caja siempre descuenta las retenciones.</p>`+price28ResultTable(s.result):'<div class="empty">Sin resultado guardado.</div>'}<p class="price28-note">${esc(s.result?.status||'')}</p><div class="modal-actions">${price28Btn('Cerrar','modal-close')}</div></div>`);return;
  }
  if(action==='commission-new'||action==='commission-edit'){price28CommissionModal(b.dataset.price28Category||'');return;}
  if(action==='mapping-new'||action==='mapping-edit'){price28MappingModal(b.dataset.price28Category||'');return;}
  const section=b.dataset.price28Section;
  if(action==='config-discard'){delete price28ConfigDrafts[section];render();return;}
  if(action==='config-remove'){price28Draft(section).splice(Number(b.dataset.price28Index),1);render();return;}
  if(action==='config-add'){const d=price28Draft(section);d.push(section==='shippingRules'?{priority:d.length+1,keyword:'',type:'Pequeño',note:''}:{label:'',rate:0});render();return;}
  if(action==='config-save'){
    const value=price28Draft(section);if(section==='shippingRules')value.forEach((r,i)=>r.priority=i+1);
    if(await price28Command('config.pricing.save',{section,value})){delete price28ConfigDrafts[section];toast('Configuración guardada. Los próximos cálculos usarán estos valores.');render();}return;
  }
});
document.addEventListener('submit',async event=>{
  if(event.target.id==='price28-signal-policy'){event.preventDefault();const values=Object.fromEntries(new FormData(event.target));if(await price28Command('config.pricing.save',{section:'pricingSignals',value:{minCashMargin:Number(values.minCashMargin)/100,peerCashRatio:Number(values.peerCashRatio)/100}})){document.getElementById('modal').close();render();}return;}
  if(event.target.id==='price28-form'){event.preventDefault();price28RefreshResult();return;}
  if(!['price28-commission-form','price28-mapping-form'].includes(event.target.id))return;
  event.preventDefault();const values=Object.fromEntries(new FormData(event.target)),engine=price28Engine();let payload,validation,type;
  if(event.target.id==='price28-commission-form'){
    payload={channel:price28ModalData.channel,category:values.category,baseRate:Number(values.baseRate)/100,premiumRate:values.premiumRate===undefined?null:Number(values.premiumRate)/100,path:values.path,note:values.note,includedMsi:price28ModalData.channel==='Liverpool'?(price28Config().settlement?.liverpoolIncludedMsi??.0355):0};
    validation=engine.validateCommission(price28Config(),payload);type='config.commission.save';
  }else{
    payload={category:values.category,channels:Object.fromEntries(engine.CHANNELS.map((c,i)=>[c,values[`channel-${i}`]])),shipping:values.shipping,note:values.note};validation=engine.validateMapping(price28Config(),payload);type='config.mapping.save';
    if(!price28ModalData.existingCategory&&(price28Config().categoryMappings||[]).some(r=>r.category.toLocaleLowerCase('es-MX')===String(payload.category).trim().toLocaleLowerCase('es-MX'))){validation.valid=false;validation.errors.push({message:'La categoría ya existe. Usa Editar para modificar su mapeo.'});}
  }
  if(!validation.valid){price28ModalError(validation.errors);return;}
  if(await price28Command(type,payload)){document.getElementById('modal').close();toast(type==='config.mapping.save'?'Mapeo guardado; excepciones por producto conservadas.':'Comisión guardada.');render();}
});

renderers.pricing=price28Page;
renderers.configuration=price28Settings;
if(!nav.some(n=>n[0]==='configuration'))nav.push(['configuration','Configuración','layers']);
window.Price28={openProduct(sku,market){price28Tab='recomendador';const f=price28Forms.recomendador;if(f.productKey!==String(sku)){f.lastPurchaseCost='';f.alternateMarketPrice='';delete f.competitorReference;}f.productKey=String(sku);if(market&&price28Targets.includes(market)){f.targetMarket=market;f.channel=price28Channel(market);}navigate('pricing');},openSettings(section='parameters'){price28SettingsTab=section;navigate('configuration');},discardDrafts(){price28ConfigDrafts={};}};
